<template>
<div class="page-pad inspect-page">
 <OpsPageHeader eyebrow="WORKSPACE / BUSINESS HEALTH" title="业务巡检" description="从任务水位到业务积压，定位影响用户体验的关键环节。"><el-select v-model="hours" aria-label="巡检时间范围" style="width:142px" @change="refresh"><el-option label="最近 24 小时" :value="24"/><el-option label="最近 3 天" :value="72"/><el-option label="最近 7 天" :value="168"/></el-select><el-button :icon="'Refresh'" :loading="loading" @click="refresh">刷新巡检</el-button></OpsPageHeader>
 <PageState :loading="loading" :error="error" :stale="stale" :updated-at="updatedAt" @retry="refresh"/>
 <template v-if="d">
  <el-alert v-if="d.error" title="本次巡检存在采集失败" description="已采集的数据仍可查看，未采集的指标显示为未知。请稍后刷新或检查数据源。" type="warning" :closable="false" show-icon/>
  <section class="inspection-summary"><div class="summary-icon" :class="{warning:risks.length || d.error}"><el-icon><component :is="d.error || risks.length ? 'Warning' : 'CircleCheck'"/></el-icon></div><div><h2>{{ d.error ? '部分业务数据暂未获取' : risks.length ? `发现 ${risks.length} 项需要关注的业务风险` : '当前巡检未发现规则风险' }}</h2><p>统计窗口：最近 {{ d.hours || hours }} 小时 · 待处理队列为当前全量水位</p></div><a v-if="risks.length" href="#business-risks" class="text-link">查看风险 <el-icon><Bottom /></el-icon></a><span v-else class="summary-badge">{{ d.error ? '部分可用' : '巡检完成' }}</span></section>
  <div class="biz-metrics"><StatCard label="AI 任务总量" :value="fmtNum(d.aiTask?.total)" unit="个" :sub="`最近 ${d.hours || hours} 小时`" icon="MagicStick"/><StatCard label="AI 处理中" :value="fmtNum(d.aiTask?.processing)" unit="个" sub="当前全量任务" icon="Loading"/><StatCard label="AI 失败率" :value="fmtNum(d.aiTask?.failRate,2)" unit="%" :color="d.aiTask?.failRate > 20 ? 'var(--ops-danger)' : undefined" :sub="`失败 ${fmtNum(d.aiTask?.failed)} / 总计 ${fmtNum(d.aiTask?.total)}`" icon="Warning"/><StatCard label="新增用户" :value="fmtNum(d.newUsers)" unit="人" :sub="`最近 ${d.hours || hours} 小时`" icon="User"/></div>
  <section class="queue-section panel"><div class="panel-title"><div><h2>业务待办队列</h2><p>实时积压水位 · 由对应业务工作台处理</p></div><span class="eyebrow muted">ACTION QUEUE</span></div><div class="queue-grid"><div v-for="item in queues" :key="item.label" class="queue-item"><span class="queue-item-icon"><el-icon><component :is="item.icon"/></el-icon></span><div><small>{{ item.label }}</small><strong class="number" :style="{color:item.warning ? 'var(--ops-warning)' : undefined}">{{ fmtNum(item.value) }}<span>{{ item.unit }}</span></strong></div><div class="queue-foot"><span><i class="status-dot" :class="item.value == null ? 'unknown' : item.warning ? 'warn' : ''"/>{{ item.value == null ? '尚未采集' : item.warning ? '需要关注' : '当前水位' }}</span><router-link v-if="item.to && canRead(item.perm)" :to="item.to" :aria-label="`查看${item.label}`"><el-icon><TopRight /></el-icon></router-link></div></div></div></section>
  <div class="biz-paths"><router-link to="/workspace/todos">处理业务待办 →</router-link><router-link to="/workspace/search">按订单 / 任务关联检索 →</router-link><router-link v-if="canRead('ops.config')" to="/workspace/settings">配置成本与服务目标 →</router-link></div>
  <el-tabs v-model="tab" class="inspection-tabs">
   <el-tab-pane label="AI 任务分析" name="ai"><div class="ai-analysis-grid"><section class="panel analysis-panel"><div class="panel-title"><div><h2>任务状态分布</h2><p>统计窗口内创建的任务</p></div></div><div v-if="!Array.isArray(d.aiTask?.statusStats)" class="empty-inline">任务分布尚未采集</div><div v-else-if="!d.aiTask.statusStats.length" class="empty-inline">统计窗口内暂无 AI 任务</div><div ref="statusEl" class="status-chart" role="img" aria-label="AI 任务各状态数量分布图"/><details class="chart-data"><summary>查看任务状态数据表</summary><table><thead><tr><th>状态</th><th>数量</th></tr></thead><tbody><tr v-for="item in statuses" :key="item.status"><td>{{item.label}}</td><td>{{fmtNum(item.cnt)}}</td></tr></tbody></table></details><div class="status-legend"><div v-for="row in statuses" :key="row.status"><span><i :style="{background:row.color}"/>{{ row.label }}</span><b class="number">{{ fmtNum(row.cnt) }}</b></div></div></section>
   <section class="panel analysis-panel"><div class="panel-title"><div><h2>任务类型表现</h2><p>成功、失败与平均处理时长</p></div><el-icon class="muted"><DataAnalysis /></el-icon></div><el-table :data="d.aiTask?.typeStats || []" :empty-text="Array.isArray(d.aiTask?.typeStats) ? '统计窗口内暂无任务' : '类型统计尚未采集'"><el-table-column label="任务类型" min-width="120"><template #default="{row}"><span class="task-type">{{ row.taskType || '未分类' }}</span></template></el-table-column><el-table-column label="总量" width="72"><template #default="{row}">{{ fmtNum(row.cnt) }}</template></el-table-column><el-table-column label="成功" width="72"><template #default="{row}"><span style="color:var(--ops-success)">{{ fmtNum(row.success) }}</span></template></el-table-column><el-table-column label="失败" width="72"><template #default="{row}"><span :style="{color:row.failed > 0 ? 'var(--ops-danger)' : undefined}">{{ fmtNum(row.failed) }}</span></template></el-table-column><el-table-column label="均耗时" min-width="90"><template #default="{row}">{{ fmtNum(row.avgSeconds,1) }} s</template></el-table-column></el-table></section></div>
   <section class="panel analysis-panel failure-panel"><div class="panel-title"><div><h2>失败原因分析</h2><p>按错误码与错误信息聚合 · 最多 10 项</p></div><el-tag type="info" effect="plain">{{ fmtNum(d.aiTask?.failed) }} 个失败任务</el-tag></div><el-table :data="d.aiTask?.failReasons || []" :empty-text="Array.isArray(d.aiTask?.failReasons) ? '统计窗口内暂无失败原因' : '失败原因尚未采集'"><el-table-column label="错误码" width="120"><template #default="{row}"><code class="error-code">{{ row.errorCode ?? '—' }}</code></template></el-table-column><el-table-column prop="errorMessage" label="错误信息" min-width="300" show-overflow-tooltip/><el-table-column label="数量" width="90"><template #default="{row}"><b class="number">{{ fmtNum(row.cnt) }}</b></template></el-table-column><el-table-column label="操作" width="100"><template #default="{row}"><el-button link type="primary" size="small" @click="copyFailure(row)">复制信息</el-button></template></el-table-column></el-table></section></el-tab-pane>
   <el-tab-pane label="业务趋势" name="business"><section class="panel analysis-panel"><div class="panel-title"><div><h2>用户与订单趋势</h2><p>按自然日聚合 · 没有记录的日期不填充虚拟值</p></div><span class="trend-legend"><i style="background:#438c80"/>新增用户<i style="background:#d98973"/>订单数量</span></div><div ref="dailyEl" class="daily-chart" role="img" aria-label="每日新增用户和订单量趋势图"/><el-empty v-if="!dailyDays.length" description="统计窗口内暂无每日数据" :image-size="64"/></section><div class="biz-metrics mini-metrics"><StatCard label="已支付订单" :value="fmtNum(d.order?.paid)" unit="笔" :sub="`最近 ${d.hours || hours} 小时`" icon="Tickets"/><StatCard label="新增用户" :value="fmtNum(d.newUsers)" unit="人" :sub="`最近 ${d.hours || hours} 小时`" icon="User"/><StatCard label="待审核退款" :value="fmtNum(d.queue?.pendingRefunds)" unit="笔" sub="当前全量队列" icon="RefreshLeft"/><StatCard label="待处理举报" :value="fmtNum(d.queue?.pendingReports)" unit="条" sub="当前全量队列" icon="Flag"/></div><section class="panel analysis-panel"><div class="panel-title"><div><h2>每日订单明细</h2><p>金额为已支付订单金额，单位元</p></div></div><el-table :data="d.orderDaily || []" empty-text="暂无每日订单数据"><el-table-column prop="day" label="日期"/><el-table-column label="订单数"><template #default="{row}">{{ fmtNum(row.cnt) }}</template></el-table-column><el-table-column label="已支付金额（元）"><template #default="{row}">{{ row.amountCents == null ? '—' : fmtNum(Number(row.amountCents)/100,2) }}</template></el-table-column></el-table></section></el-tab-pane>
  </el-tabs>
  <section id="business-risks" class="panel analysis-panel risk-panel"><div class="panel-title"><div><h2>业务风险清单 <span class="risk-count">{{ risks.length }}</span></h2><p>基于当前业务规则生成，按巡检窗口刷新</p></div><el-icon class="muted"><Warning /></el-icon></div><div v-if="!Array.isArray(d.risks)" class="empty-inline">风险信息尚未采集，请重试巡检</div><div v-else-if="!risks.length" class="risk-empty"><el-icon><CircleCheck /></el-icon><span>本次巡检未发现规则风险</span></div><div v-for="(risk,index) in risks" :key="`${risk.title}-${index}`" class="risk-row"><span class="risk-index number">{{ String(index+1).padStart(2,'0') }}</span><el-tag :type="risk.level === 'danger' ? 'danger' : risk.level === 'warning' ? 'warning' : 'info'" size="small">{{ risk.level === 'danger' ? '高风险' : risk.level === 'warning' ? '需关注' : '提示' }}</el-tag><div><b>{{ risk.title }}</b><p>{{ risk.detail }}</p></div><button v-if="String(risk.title).includes('AI')" class="text-link" @click="openAi">查看任务分析 <el-icon><Right /></el-icon></button><router-link v-else-if="canRead('ops.audit') && (String(risk.title).includes('举报') || String(risk.title).includes('作品'))" to="/audit/content" class="text-link">查看内容审计 <el-icon><Right /></el-icon></router-link></div></section>
