<script setup lang="ts">
import { computed, nextTick, ref } from 'vue'
import * as ops from '@/api/ops'
import { useUserStore } from '@/stores/user'
import { useAppStore } from '@/stores/app'
import { usePolling } from '@/composables/usePolling'
import { useChart } from '@/utils/echarts'
import { copyText } from '@/utils/copy'
import StatCard from '@/components/StatCard.vue'
import OpsPageHeader from '@/components/OpsPageHeader.vue'
import PageState from '@/components/PageState.vue'
import { hasModulePermission } from '@/utils/authPolicy'
const d = ref<any>(null), hours = ref(24), tab = ref('ai'), user = useUserStore(), app = useAppStore(), statusEl = ref<HTMLElement|null>(null), dailyEl = ref<HTMLElement|null>(null)
function canRead(module:string){return hasModulePermission(user.perms,module,'read')}
function fmtNum(value: unknown, digits = 0) { return value == null || value === '' || !Number.isFinite(Number(value)) ? '—' : Number(value).toLocaleString('zh-CN',{maximumFractionDigits:digits}) }
async function load() { const result = await ops.bizInspect(hours.value); if (!result || typeof result !== 'object') throw new Error('业务巡检返回格式异常'); d.value = result }
const {loading,error,stale,updatedAt,refresh} = usePolling(load,{interval:60000})
const risks = computed<any[]>(() => Array.isArray(d.value?.risks) ? d.value.risks : [])
const queues = computed(() => [{label:'AI 待处理',value:d.value?.aiTask?.pending,unit:'个',icon:'MagicStick',warning:d.value?.aiTask?.pending > (d.value?.thresholds?.aiPending ?? 50),to:'/workspace/todos?type=AI_PENDING',perm:'ops.view'},{label:'待审核作品',value:d.value?.queue?.pendingWorks,unit:'个',icon:'Picture',warning:d.value?.queue?.pendingWorks > (d.value?.thresholds?.pendingWorks ?? 20),to:'/workspace/todos?type=WORK',perm:'ops.view'},{label:'待审核退款',value:d.value?.queue?.pendingRefunds,unit:'笔',icon:'RefreshLeft',warning:d.value?.queue?.pendingRefunds > 0,to:'/workspace/todos?type=REFUND',perm:'ops.view'},{label:'待处理举报',value:d.value?.queue?.pendingReports,unit:'条',icon:'Flag',warning:d.value?.queue?.pendingReports > 0,to:'/workspace/todos?type=REPORT',perm:'ops.view'}])
const statusMeta:Record<string,{label:string;color:string}> = {'0':{label:'待处理',color:'#bdac8b'},'1':{label:'处理中',color:'#d7ac6a'},'2':{label:'已成功',color:'#438c80'},'3':{label:'已失败',color:'#d98973'},'4':{label:'已取消',color:'#8b9691'}}
const statuses = computed(() => (d.value?.aiTask?.statusStats || []).map((row:any) => ({...row,...(statusMeta[String(row.status)] || {label:`状态 ${row.status}`,color:'#899791'})})))
const statusOption = computed(() => ({tooltip:{trigger:'item'},series:[{name:'任务状态',type:'pie',radius:['58%','80%'],center:['50%','50%'],label:{show:false},itemStyle:{borderRadius:3,borderColor:app.theme === 'dark' ? '#222a2e' : '#fff',borderWidth:3},data:statuses.value.map((row:any) => ({name:row.label,value:row.cnt,itemStyle:{color:row.color}}))}],graphic:[{type:'text',left:'center',top:'40%',style:{text:fmtNum(d.value?.aiTask?.total),fill:app.theme === 'dark' ? '#e8edeb' : '#252a2e',fontSize:27,fontWeight:700,fontFamily:'Bahnschrift'}},{type:'text',left:'center',top:'59%',style:{text:'窗口内任务',fill:'#89928c',fontSize:12}}]}))
const dailyDays = computed<string[]>(() => [...new Set<string>([...(d.value?.userDaily || []).map((r:any) => String(r.day)),...(d.value?.orderDaily || []).map((r:any) => String(r.day))])].sort())
const dailyOption = computed(() => ({tooltip:{trigger:'axis'},grid:{left:40,right:20,top:20,bottom:30},xAxis:{type:'category',data:dailyDays.value,axisTick:{show:false},axisLine:{show:false},axisLabel:{color:'#89928c',fontSize:12}},yAxis:{type:'value',minInterval:1,axisLabel:{color:'#89928c',fontSize:12},splitLine:{lineStyle:{color:app.theme === 'dark' ? '#344044' : '#eeeee8',type:'dashed'}}},series:[{name:'新增用户',type:'bar',barMaxWidth:24,itemStyle:{color:'#438c80',borderRadius:[3,3,0,0]},data:dailyDays.value.map(day => d.value?.userDaily?.find((r:any) => String(r.day) === day)?.cnt ?? null)},{name:'订单数量',type:'bar',barMaxWidth:24,itemStyle:{color:'#d98973',borderRadius:[3,3,0,0]},data:dailyDays.value.map(day => d.value?.orderDaily?.find((r:any) => String(r.day) === day)?.cnt ?? null)}]}))
useChart(statusEl,statusOption)
useChart(dailyEl,dailyOption)
async function copyFailure(row:any) { await copyText(`[${row.errorCode ?? '未知错误码'}] ${row.errorMessage || '无错误信息'}`) }
async function openAi() { tab.value = 'ai'; await nextTick(); document.querySelector('.inspection-tabs')?.scrollIntoView({behavior:'smooth',block:'start'}) }
</script>
